/**
 * Bundled Sample Survey Dataset & Export Generator
 */

window.loadBundledSample = function() {
  if (window.SurveyApp && window.__BUNDLED_SAMPLE_ROWS__) {
    window.SurveyApp.processAudit(window.__BUNDLED_SAMPLE_ROWS__, 'Content_Export_MENTORMasterGER1_Test-GER-1.xlsx');
  }
};

window.exportAuditIssuesCSV = function() {
  if (typeof window.triggerCSVExport === 'function') {
    window.triggerCSVExport();
  }
};

window.triggerCSVExport = function(auditResult) {
  const result = auditResult || window.__LAST_AUDIT_RESULT__;
  if (!result || !result.columns) {
    alert('Please upload or load a survey export before exporting issues.');
    return;
  }

  // Filter issues (Missing Options 🔴, Incomplete 🟡, or any column with issues)
  const issueCols = result.columns.filter(c => c.status === 'missing_options' || c.status === 'incomplete' || (c.issues && c.issues.length > 0));

  if (issueCols.length === 0) {
    alert('No discrepancies or audit issues were found in this dataset! Everything is 100% harmonized.');
    return;
  }

  const csvRows = [];
  // CSV Headers
  csvRows.push([
    'Column_Index',
    'Status',
    'Variable_Name',
    'Original_Variable_ID',
    'Section',
    'Question_Header',
    'Scale_Type',
    'Canonical_Options_Count',
    'Observed_Options_Count',
    'Issues_Detected',
    'Unmapped_Observed_Values'
  ].map(escapeCSV).join(','));

  // CSV Data Rows
  issueCols.forEach(col => {
    const varName = col.canonical ? col.canonical.variable : (col.extractedId || `col_${col.colIndex}`);
    const origVar = col.canonical ? col.canonical.orig_variable : (col.extractedId || '-');
    const section = col.canonical ? col.canonical.section : 'Uncategorized';
    const scale = col.canonical ? `${col.canonical.scale} (${col.canonical.question_type})` : 'Unknown';
    const nCan = col.canonicalOptions ? col.canonicalOptions.length : 0;
    const nObs = col.observedValues ? col.observedValues.length : 0;
    const issuesText = col.issues.map(i => i.message).join('; ');
    const unmappedText = col.unmappedObserved.map(u => typeof u === 'string' ? u : u.label).join('; ');

    csvRows.push([
      col.colIndex + 1,
      col.statusLabel,
      varName,
      origVar,
      section,
      col.cleanedText || col.rawHeader,
      scale,
      nCan,
      nObs,
      issuesText,
      unmappedText
    ].map(escapeCSV).join(','));
  });

  const csvString = '\uFEFF' + csvRows.join('\r\n'); // Add UTF-8 BOM for Excel compatibility
  const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `JA_MENTOR_Youth_Survey_Audit_Issues_${(result.filename || 'export').replace(/\.[^/.]+$/, '')}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

function escapeCSV(val) {
  if (val == null) return '""';
  const str = String(val).replace(/"/g, '""');
  return `"${str}"`;
}

